package com.johnny.hotel.invoice;import com.johnny.hotel.common.Result;import lombok.RequiredArgsConstructor;import org.springframework.security.access.prepost.PreAuthorize;import org.springframework.web.bind.annotation.*;import java.util.*;
@RestController @RequestMapping("/api/finance/operations") @RequiredArgsConstructor @PreAuthorize("hasRole('FINANCE')") public class FinanceReadController{private final FinanceReadService service;@GetMapping("/{domain}")public Result<List<Map<String,Object>>> read(@PathVariable String domain,@RequestParam(required=false)Integer page,@RequestParam(required=false)Integer size){return Result.success(service.read(domain,page,size));}}
